  "prediction_basis_card_ids": ["C65","C67","C71","C73","C75","C68","C70","C72","C74","C76"],
  "claims": [
    {
      "claim": "L6 isolated perfused rat liver records show morphine hepatic clearance of 26.0–26.8 mL/min, approaching the 30 mL/min perfusate flow, indicating near-flow-limited hepatic extraction.",
      "card_ids": ["C65","C67","C71","C73","C75"]
    },
    {
      "claim": "Human and rat hepatocyte/microsomal intrinsic-clearance records show substantial morphine glucuronidation (human hepatocyte CLint 17–28 µL/min/10^6 cells; UGT2B7-mediated M3G/M6G formation), consistent with extensive first-pass metabolism.",
      "card_ids": ["C68","C70","C72","C74","C76"]
    },
    {
      "claim": "Naloxone retains the free phenolic 3-OH and morphinan ether scaffold of morphine, and its 6-keto and N-allyl substituents add carbonyl-reduction and N-dealkylation soft spots; the near-flow-limited first-pass clearance documented for morphine therefore transfers to naloxone and supports F < 20%.",
      "card_ids": ["C65","C71","C75"]
    },
    {
      "claim": "The prior high-F evidence from codeine (80.5%) and ethylmorphine (28–74%) is less transferable because their 3-O-alkyl groups block the major phenolic glucuronidation site, whereas naloxone has a free 3-phenol like morphine; morphine's own F is only 29.2 ± 7.2%, just above the threshold.",
      "card_ids": ["C07","C03","C06","C08","C10"]
    },
    {
      "claim": "Diacetylmorphine-derived morphine F estimates of 57–61% reflect morphine after prodrug conversion and do not address naloxone's own first-pass metabolism.",
      "card_ids": ["C25","C28"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "changed",
      "card_ids": ["C65","C67","C71","C73","C75","C68","C70","C72","C74","C76"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement for naloxone is present in the supplied records.",
    "L6 hepatic-clearance records are for morphine, not naloxone; transfer is structural/mechanistic rather than direct.",
    "No naloxone-specific metabolic stability, intrinsic clearance, or first-pass extraction data are supplied.",
    "No direct naloxone absorption or solubility experiment is supplied; absorption is inferred from physicochemical priors and morphine analog data.",
    "The quantitative contribution of naloxone's 6-keto reduction and N-allyl N-dealkylation to first-pass loss is not measured in the supplied records."
  ],
  "decision_summary": "Predicted low because L6 hepatic-clearance records show near-flow-limited first-pass extraction for the closest morphinan analog morphine, and naloxone retains the free phenolic glucuronidation site while adding 6-keto and N-allyl metabolic soft spots; the prior high evidence from codeine/ethylmorphine is less transferable because their 3-O-alkyl groups block phenolic glucuronidation, and morphine's own F is only 29.2%, just above the 20% threshold. Confidence is moderate because no direct naloxone bioavailability measurement is supplied."
}

